export type AccentColor = keyof typeof ACCENT_PALETTES;

/** Shades de la escala de Tailwind (orden ascendente, mismo formato del @theme). */
const SHADES = [50, 100, 200, 300, 400, 500, 600, 700, 800, 900, 950] as const;

/**
 * Override del acento para concatenar al CSS base: bloque :root,:host con los
 * fallbacks surface y las variables del acento (11 shades + 11 referencias
 * accent), más las reglas de utilidad con hex-alpha que Tailwind calcula por
 * acento. Todo sin @layer: gana sobre las reglas del base (theme y
 * utilities), y el render coincide con una compilación directa de Tailwind.
 */
export function accentOverrideBlock(accent: AccentColor): string {
  const palette = ACCENT_PALETTES[accent];
  const surfaceVars = `--color-surface-light:${palette.light};--color-surface-dark:${palette.dark};`;
  const colorVars = SHADES.map((s) => `--color-${accent}-${s}:${palette[s]};`).join('');
  const accentVars = SHADES.map((s) => `--color-accent-${s}:var(--color-${accent}-${s});`).join('');
  return `:root,:host{${surfaceVars}${colorVars}${accentVars}}\n${palette.rules}`;
}
